const ENTRIES = [{"id": 1, "cat": "Fundamentos", "name": "Workflow", "desc": "Uma sequência visual de nós conectados que transforma dados em resultados.", "steps": "Crie um workflow; adicione uma fonte de dados; conecte nós; configure e execute em ordem.", "tip": "Anote objetivo, entrada e saída para facilitar a manutenção.", "tags": "fluxo pipeline início"}, {"id": 2, "cat": "Fundamentos", "name": "Estados dos nós", "desc": "O estado indica se o nó precisa de configuração, está pronto ou foi executado.", "steps": "Vermelho: não configurado. Amarelo: configurado. Verde: executado. Inspecione mensagens de aviso e erro.", "tip": "As representações visuais podem variar entre interfaces e versões.", "tags": "semáforo erro"}, {"id": 3, "cat": "Fundamentos", "name": "Portas e conexões", "desc": "Nós podem transportar tabelas, modelos, variáveis e outros objetos.", "steps": "Conecte portas compatíveis; consulte a documentação do nó para saber o tipo esperado.", "tip": "Um modelo treinado e uma tabela de teste entram em portas diferentes do Predictor.", "tags": "port model"}, {"id": 4, "cat": "Fundamentos", "name": "Configurar, executar e resetar", "desc": "Configurar define parâmetros; executar calcula saídas; resetar descarta o resultado.", "steps": "Abra a configuração; selecione colunas; execute; inspecione a tabela de saída.", "tip": "Alterar um nó pode exigir a reexecução dos nós posteriores.", "tags": "execute reset"}, {"id": 5, "cat": "Fundamentos", "name": "Repositório e extensões", "desc": "Encontre nós pelo nome em inglês e instale integrações quando necessário.", "steps": "Busque o nome; leia a descrição; confira entradas, saídas e extensão necessária.", "tip": "Nós ausentes podem depender de extensão ou ter substitutos em versões recentes.", "tags": "install hub"}, {"id": 6, "cat": "Fundamentos", "name": "Component vs. Metanode", "desc": "Ambos organizam grupos de nós; componentes permitem encapsular configuração e interfaces reutilizáveis.", "steps": "Agrupe etapas relacionadas; use Component para reutilização e configuração; Metanode para organização local.", "tip": "Prefira interfaces de entrada e saída simples.", "tags": "componente"}, {"id": 7, "cat": "Fundamentos", "name": "Flow variables", "desc": "Valores que controlam configurações dos nós durante a execução.", "steps": "Crie uma variável; conecte a porta de variáveis; associe-a ao parâmetro na configuração.", "tip": "Nome e tipo da variável precisam ser compatíveis com o parâmetro.", "tags": "variáveis parâmetros"}, {"id": 8, "cat": "Fundamentos", "name": "Documentação do workflow", "desc": "Rótulos e anotações tornam o fluxo compreensível.", "steps": "Nomeie blocos: entrada, limpeza, modelagem e avaliação; registre hipóteses e decisões.", "tip": "Inclua origem dos dados, semente aleatória e critério de seleção do modelo.", "tags": "boas práticas"}, {"id": 9, "cat": "Entrada e saída", "name": "CSV Reader", "desc": "Importa arquivos CSV e outros textos delimitados.", "steps": "Confira caminho, separador, cabeçalho, aspas, encoding e tipos de coluna.", "tip": "Vírgula decimal e ponto e vírgula como separador são comuns em bases brasileiras.", "tags": "importar leitura"}, {"id": 10, "cat": "Entrada e saída", "name": "Excel Reader", "desc": "Lê planilhas e intervalos de arquivos Excel.", "steps": "Selecione o arquivo, a aba, a linha de cabeçalho e o intervalo.", "tip": "Colunas com números misturados a texto podem ser importadas como string.", "tags": "xlsx"}, {"id": 11, "cat": "Entrada e saída", "name": "Table Creator", "desc": "Cria uma pequena tabela manual para testes.", "steps": "Defina nomes e tipos de coluna; preencha algumas linhas; execute.", "tip": "Use dados pequenos para testar uma regra antes de processar toda a base.", "tags": "manual"}, {"id": 12, "cat": "Entrada e saída", "name": "List Files/Folders", "desc": "Lista arquivos para processamento em lote.", "steps": "Selecione a pasta; filtre extensão; use os caminhos em um loop de leitura.", "tip": "Ordene e valide a lista antes de combinar arquivos.", "tags": "pasta batch"}, {"id": 13, "cat": "Entrada e saída", "name": "CSV Writer / Excel Writer", "desc": "Exporta tabelas para arquivos externos.", "steps": "Escolha destino; configure sobrescrita, cabeçalho e formato; execute.", "tip": "Confirme o conteúdo exportado e evite sobrescrever a base original.", "tags": "exportar salvar"}, {"id": 14, "cat": "Entrada e saída", "name": "Table Reader / Table Writer", "desc": "Lê e grava tabelas no formato de tabela do KNIME.", "steps": "Use para persistir resultados intermediários ou transportar tabelas entre fluxos.", "tip": "Formato de tabela preserva tipos melhor que CSV.", "tags": "persistência"}, {"id": 15, "cat": "Entrada e saída", "name": "GET Request / JSON Path", "desc": "Obtém dados de APIs e extrai campos de JSON.", "steps": "Configure URL, cabeçalhos e autenticação; valide status; extraia campos e expanda listas.", "tip": "Respeite paginação, limites da API e tratamento de respostas vazias.", "tags": "api rest json"}, {"id": 16, "cat": "Limpeza e transformação", "name": "Column Filter", "desc": "Mantém ou remove colunas.", "steps": "Selecione atributos úteis; remova IDs sem significado preditivo e colunas redundantes.", "tip": "Não deixe o alvo ou atributos derivados dele entrarem nas features.", "tags": "colunas seleção"}, {"id": 17, "cat": "Limpeza e transformação", "name": "Row Filter / Rule-based Row Filter", "desc": "Filtra linhas por valor, intervalo ou condição.", "steps": "Defina coluna e critério; confira quantidade de linhas antes e depois.", "tip": "Filtros excessivos podem alterar a distribuição da população.", "tags": "linhas"}, {"id": 18, "cat": "Limpeza e transformação", "name": "Missing Value", "desc": "Trata valores ausentes por estratégias por tipo ou coluna.", "steps": "Escolha média, mediana, valor fixo ou outra estratégia adequada; inspecione a saída.", "tip": "Para avaliação de ML, estime parâmetros de imputação apenas no treino.", "tags": "faltantes nulos"}, {"id": 19, "cat": "Limpeza e transformação", "name": "Duplicate Row Filter", "desc": "Remove ou identifica registros repetidos.", "steps": "Selecione as colunas que definem duplicidade; decida qual ocorrência manter.", "tip": "Registros distintos podem ter atributos iguais: valide a chave de negócio.", "tags": "duplicatas"}, {"id": 20, "cat": "Limpeza e transformação", "name": "String to Number / Number to String", "desc": "Converte tipos entre texto e valores numéricos.", "steps": "Selecione colunas; ajuste convenções de separador decimal; confira falhas.", "tip": "Remova símbolos de moeda e espaços antes da conversão quando necessário.", "tags": "tipos conversão"}, {"id": 21, "cat": "Limpeza e transformação", "name": "String to Date&Time", "desc": "Converte texto em datas e horários.", "steps": "Informe o padrão correspondente à entrada; confira fuso e valores inválidos.", "tip": "dd/MM/yyyy e MM/dd/yyyy têm significados diferentes.", "tags": "datas"}, {"id": 22, "cat": "Limpeza e transformação", "name": "String Manipulation", "desc": "Limpa, combina ou extrai partes de textos.", "steps": "Selecione a coluna; monte a expressão na configuração; escolha substituir ou criar coluna.", "tip": "Confira espaços, acentos e diferenças de caixa antes de comparar categorias.", "tags": "texto"}, {"id": 23, "cat": "Limpeza e transformação", "name": "Math Formula", "desc": "Calcula uma coluna numérica com uma expressão.", "steps": "Escolha a fórmula; referencie colunas; crie uma coluna de saída com nome claro.", "tip": "Proteja divisões por zero e confira valores ausentes.", "tags": "fórmula cálculo"}, {"id": 24, "cat": "Limpeza e transformação", "name": "Rule Engine", "desc": "Cria uma coluna a partir de regras avaliadas de cima para baixo.", "steps": "Escreva condições e resultados; termine com uma regra padrão TRUE.", "tip": "A primeira regra verdadeira define o resultado.", "tags": "regras if"}, {"id": 25, "cat": "Limpeza e transformação", "name": "Column Rename / Column Resorter", "desc": "Renomeia e reorganiza colunas.", "steps": "Use nomes consistentes; posicione chaves, atributos e alvo em uma ordem compreensível.", "tip": "Registre mudanças de nomes usadas por nós posteriores.", "tags": "nomes"}, {"id": 26, "cat": "Limpeza e transformação", "name": "Joiner", "desc": "Combina tabelas por chaves.", "steps": "Escolha chaves e tipo de junção: inner, left, right ou full outer; confira cardinalidade.", "tip": "Chaves repetidas em ambas as tabelas podem multiplicar linhas.", "tags": "join merge"}, {"id": 27, "cat": "Limpeza e transformação", "name": "Concatenate", "desc": "Empilha tabelas por linhas.", "steps": "Confira nomes e tipos de coluna; defina como tratar colunas ausentes.", "tip": "Empilhar linhas é diferente de juntar colunas por chave.", "tags": "union"}, {"id": 28, "cat": "Limpeza e transformação", "name": "GroupBy", "desc": "Agrupa linhas e calcula agregações.", "steps": "Defina chaves de grupo e operações como soma, média, contagem ou máximo.", "tip": "Contagem de linhas e contagem de valores não ausentes podem diferir.", "tags": "agregação"}, {"id": 29, "cat": "Limpeza e transformação", "name": "Pivoting / Unpivoting", "desc": "Transforma dados entre formato largo e longo.", "steps": "Escolha identificadores, categorias e valores; defina agregação para o pivot.", "tip": "Confira se combinações de chave e categoria são únicas.", "tags": "pivot tabela"}, {"id": 30, "cat": "Limpeza e transformação", "name": "Normalizer / Normalizer (Apply)", "desc": "Escala atributos numéricos e reutiliza a transformação aprendida.", "steps": "Ajuste no treino; aplique a mesma transformação no teste; exclua o alvo.", "tip": "KNN, SVM e métodos de distância são sensíveis à escala.", "tags": "normalização zscore minmax"}, {"id": 31, "cat": "Limpeza e transformação", "name": "One to Many", "desc": "Converte categorias em colunas indicadoras.", "steps": "Selecione colunas categóricas; aplique um esquema consistente entre treino e produção.", "tip": "Categorias novas no teste exigem tratamento definido.", "tags": "one hot encoding"}, {"id": 32, "cat": "Limpeza e transformação", "name": "Numeric Outliers", "desc": "Identifica ou trata valores numéricos extremos.", "steps": "Selecione colunas; examine limites e estratégia de tratamento.", "tip": "Um extremo pode ser um evento real; não remova sem critério de domínio.", "tags": "outlier IQR"}, {"id": 33, "cat": "Limpeza e transformação", "name": "Sorter / Rank", "desc": "Ordena registros ou atribui posições.", "steps": "Escolha colunas e sentido; defina desempates quando necessário.", "tip": "Ordene por data antes de criar atributos temporais.", "tags": "ordenação ranking"}, {"id": 34, "cat": "Exploração e gráficos", "name": "Statistics", "desc": "Resume distribuição e qualidade dos atributos.", "steps": "Examine mínimos, máximos, médias, dispersão e faltantes por coluna.", "tip": "Estatística global pode ocultar diferenças entre grupos.", "tags": "descritiva"}, {"id": 35, "cat": "Exploração e gráficos", "name": "Histogram", "desc": "Mostra a distribuição de uma variável numérica.", "steps": "Escolha coluna e número de intervalos; observe assimetria e valores extremos.", "tip": "Compare distribuições de treino e teste para detectar mudanças.", "tags": "distribuição"}, {"id": 36, "cat": "Exploração e gráficos", "name": "Scatter Plot", "desc": "Explora a relação entre duas variáveis.", "steps": "Selecione eixos; use cor por classe quando disponível.", "tip": "Correlação visual não demonstra causalidade.", "tags": "dispersão"}, {"id": 37, "cat": "Exploração e gráficos", "name": "Box Plot", "desc": "Compara dispersão e mediana entre grupos.", "steps": "Escolha variável numérica e categoria de agrupamento.", "tip": "Pontos extremos merecem investigação, não exclusão automática.", "tags": "boxplot"}, {"id": 38, "cat": "Exploração e gráficos", "name": "Bar Chart / Line Plot", "desc": "Compara categorias ou mostra evolução ordenada.", "steps": "Agregue os dados; use barras para categorias e linha para séries ordenadas.", "tip": "Para tempo, ordene datas e confira a frequência das observações.", "tags": "gráfico"}, {"id": 39, "cat": "Exploração e gráficos", "name": "Linear Correlation", "desc": "Calcula correlação linear entre colunas numéricas.", "steps": "Selecione atributos; examine pares redundantes e relações com o alvo.", "tip": "Correlação baixa não exclui relações não lineares.", "tags": "pearson"}, {"id": 40, "cat": "Exploração e gráficos", "name": "Data Explorer / Table View", "desc": "Inspeciona dados e padrões de qualidade.", "steps": "Confira amostras, tipos, cardinalidade, distribuição e faltantes.", "tip": "Visualizações e nomes podem depender da extensão e versão instalada.", "tags": "explorar dashboard"}, {"id": 41, "cat": "Machine learning", "name": "Learner → Predictor", "desc": "O Learner aprende um modelo; o Predictor o aplica a novas linhas.", "steps": "Conecte treino ao Learner; conecte modelo e tabela de teste ao Predictor; avalie previsões.", "tip": "A tabela de teste precisa ter atributos compatíveis com o treino.", "tags": "modelo"}, {"id": 42, "cat": "Machine learning", "name": "Decision Tree Learner / Predictor", "desc": "Classifica com regras de divisão em árvore.", "steps": "Selecione alvo categórico; ajuste profundidade ou tamanho mínimo de nós quando disponíveis.", "tip": "Árvores profundas podem memorizar os exemplos de treino.", "tags": "árvore classificação"}, {"id": 43, "cat": "Machine learning", "name": "Random Forest Learner / Predictor", "desc": "Combina árvores para classificação ou regressão, conforme o nó escolhido.", "steps": "Escolha a variante adequada; configure número de árvores, amostragem e semente.", "tip": "Compare com um modelo simples e avalie fora do treino.", "tags": "floresta ensemble"}, {"id": 44, "cat": "Machine learning", "name": "Logistic Regression Learner / Predictor", "desc": "Estima probabilidades de classes em classificação.", "steps": "Defina alvo; codifique categorias conforme o nó; examine regularização e probabilidades.", "tip": "O nome inclui regressão, mas seu uso típico aqui é classificação.", "tags": "logística"}, {"id": 45, "cat": "Machine learning", "name": "Naive Bayes Learner / Predictor", "desc": "Classificador probabilístico com hipótese de independência condicional.", "steps": "Escolha alvo e atributos compatíveis; treine; avalie por classe.", "tip": "A hipótese simplifica o problema; a qualidade deve ser medida empiricamente.", "tags": "bayes"}, {"id": 46, "cat": "Machine learning", "name": "K Nearest Neighbor", "desc": "Classifica a partir de exemplos próximos.", "steps": "Selecione alvo e k; normalize atributos; escolha distância quando disponível.", "tip": "k pequeno aumenta sensibilidade a ruído; k grande suaviza decisões.", "tags": "KNN vizinhos"}, {"id": 47, "cat": "Machine learning", "name": "SVM Learner / Predictor", "desc": "Aprende uma fronteira de decisão controlada por kernel e regularização.", "steps": "Normalize atributos; escolha kernel e parâmetros; ajuste por validação.", "tip": "Escala e configuração afetam fortemente o resultado.", "tags": "support vector"}, {"id": 48, "cat": "Machine learning", "name": "Linear Regression Learner / Regression Predictor", "desc": "Prevê um alvo numérico por uma combinação dos atributos.", "steps": "Escolha alvo contínuo; trate categorias; avalie resíduos e métricas no teste.", "tip": "Examine colinearidade e relações que o modelo linear não representa.", "tags": "regressão"}, {"id": 49, "cat": "Machine learning", "name": "Gradient Boosted Trees", "desc": "Combina árvores sequencialmente para melhorar previsões.", "steps": "Escolha nós de classificação ou regressão; ajuste árvores, profundidade e learning rate.", "tip": "Use validação para controlar complexidade e overfitting.", "tags": "boosting"}, {"id": 50, "cat": "Machine learning", "name": "Desbalanceamento de classes", "desc": "Classes raras podem ser ignoradas por um modelo com alta acurácia.", "steps": "Inspecione proporções; avalie precision, recall e F1 por classe; ajuste pesos ou reamostragem.", "tip": "Reamostragem pertence ao treino, dentro de cada fold de validação.", "tags": "SMOTE imbalance"}, {"id": 51, "cat": "Machine learning", "name": "Seleção de atributos", "desc": "Reduz atributos irrelevantes e redundantes.", "steps": "Comece com critérios de domínio; compare desempenho e estabilidade usando validação.", "tip": "Selecionar atributos com toda a base antes da avaliação também causa vazamento.", "tags": "features"}, {"id": 52, "cat": "Machine learning", "name": "Persistência do modelo", "desc": "Guarda modelos e transformações para inferência posterior.", "steps": "Use portas e writers compatíveis; salve junto o pré-processamento e o esquema de atributos.", "tip": "PMML não suporta todos os modelos; confira compatibilidade antes de exportar.", "tags": "PMML model writer"}, {"id": 53, "cat": "Validação e métricas", "name": "Partitioning", "desc": "Separa dados em treino e teste.", "steps": "Exemplo: 70% treino e 30% teste; fixe semente; use estratificação para classes quando apropriado.", "tip": "Em séries temporais, preserve a ordem e não embaralhe o futuro com o passado.", "tags": "split 70 30"}, {"id": 54, "cat": "Validação e métricas", "name": "X-Partitioner / X-Aggregator", "desc": "Organiza validação cruzada por folds.", "steps": "Configure k folds; execute treinamento e previsão dentro do loop; reúna previsões e avalie.", "tip": "Ajuste imputação, normalização e PCA novamente no treino de cada fold.", "tags": "cross validation"}, {"id": 55, "cat": "Validação e métricas", "name": "Scorer", "desc": "Compara classe real e prevista.", "steps": "Selecione coluna real e coluna predita; examine matriz de confusão e métricas por classe.", "tip": "Acurácia sozinha é insuficiente em bases desbalanceadas.", "tags": "classificação"}, {"id": 56, "cat": "Validação e métricas", "name": "Precision, Recall e F1", "desc": "Precision mede a confiabilidade dos positivos; recall mede cobertura dos positivos reais.", "steps": "Precision = TP/(TP+FP); Recall = TP/(TP+FN); F1 = 2PR/(P+R).", "tip": "Declare a classe positiva e como são tratadas divisões por zero.", "tags": "métricas"}, {"id": 57, "cat": "Validação e métricas", "name": "Matriz de confusão", "desc": "Cruza rótulos reais e previsões por classe.", "steps": "Identifique TP, TN, FP e FN a partir dos rótulos; observe onde o modelo mais erra.", "tip": "Confirme a orientação dos eixos antes de interpretar as células.", "tags": "confusion matrix"}, {"id": 58, "cat": "Validação e métricas", "name": "ROC Curve / AUC", "desc": "Avalia a ordenação de probabilidades ao variar o limiar de classificação.", "steps": "Use probabilidades para a classe positiva; compare AUC e pontos de operação.", "tip": "Em classes muito raras, complemente com curva precision-recall.", "tags": "roc auc"}, {"id": 59, "cat": "Validação e métricas", "name": "Numeric Scorer", "desc": "Avalia previsões numéricas.", "steps": "Selecione valor real e previsto; compare MAE, RMSE e R² quando disponíveis.", "tip": "MAE e RMSE têm a unidade do alvo; RMSE penaliza mais erros grandes.", "tags": "regressão"}, {"id": 60, "cat": "Validação e métricas", "name": "R² e baseline", "desc": "R² mede ajuste relativo a uma referência baseada na média.", "steps": "Compare com previsão simples; inspecione erros por segmento e amplitude do alvo.", "tip": "R² pode ser negativo em dados de teste.", "tags": "baseline"}, {"id": 61, "cat": "Validação e métricas", "name": "Parameter Optimization Loop", "desc": "Busca combinações de hiperparâmetros.", "steps": "Defina espaço de busca; avalie cada combinação por validação; escolha a métrica adequada.", "tip": "Reserve o teste final; não o use para escolher parâmetros.", "tags": "otimização grid search"}, {"id": 62, "cat": "Validação e métricas", "name": "Data leakage", "desc": "Ocorre quando informações indisponíveis na previsão chegam ao treinamento ou à seleção.", "steps": "Separe treino e teste antes de ajustar transformações; remova proxies do alvo; respeite grupos e datas.", "tip": "Normalizar treino e teste separadamente também cria transformações incompatíveis.", "tags": "vazamento"}, {"id": 63, "cat": "Validação e métricas", "name": "Validação temporal", "desc": "Simula previsão de observações futuras.", "steps": "Treine no passado; valide em um intervalo posterior; avance as janelas conforme o cenário.", "tip": "Features devem usar apenas informações disponíveis no instante da previsão.", "tags": "time series walk forward"}, {"id": 64, "cat": "Validação e métricas", "name": "Overfitting / Underfitting", "desc": "Overfitting: boa memorização e baixa generalização. Underfitting: modelo pouco expressivo.", "steps": "Compare resultados de treino e validação; ajuste complexidade, atributos e regularização.", "tip": "Compare modelos sob a mesma divisão e a mesma métrica.", "tags": "generalização"}, {"id": 65, "cat": "PCA e clustering", "name": "PCA Compute / PCA Apply", "desc": "Aprende uma projeção e transforma atributos em componentes principais.", "steps": "Use atributos numéricos; trate faltantes; ajuste escala no treino; aprenda PCA no treino e aplique ao teste.", "tip": "Não inclua a coluna alvo no PCA.", "tags": "redução dimensionalidade"}, {"id": 66, "cat": "PCA e clustering", "name": "Variância explicada", "desc": "Indica quanta variabilidade os componentes preservam.", "steps": "Escolha componentes por variância acumulada e valide o efeito no objetivo final.", "tip": "Preservar 95% é uma referência possível, não uma regra universal.", "tags": "componentes"}, {"id": 67, "cat": "PCA e clustering", "name": "K-Means", "desc": "Agrupa exemplos por proximidade a centroides.", "steps": "Normalize atributos; escolha k; fixe semente; inspecione grupos e perfis.", "tip": "Não use códigos numéricos de categorias como distâncias sem justificativa.", "tags": "clusters"}, {"id": 68, "cat": "PCA e clustering", "name": "DBSCAN", "desc": "Agrupa regiões densas e identifica ruído.", "steps": "Escolha distância, raio de vizinhança e mínimo de pontos conforme implementação.", "tip": "A escala dos atributos muda a noção de vizinhança.", "tags": "densidade"}, {"id": 69, "cat": "PCA e clustering", "name": "Hierarchical Clustering", "desc": "Organiza agrupamentos em uma hierarquia.", "steps": "Escolha distância e ligação; examine o dendrograma e um ponto de corte.", "tip": "Custo de memória pode crescer muito com o número de linhas.", "tags": "dendrograma"}, {"id": 70, "cat": "PCA e clustering", "name": "t-SNE", "desc": "Projeta dados para exploração visual de vizinhanças.", "steps": "Normalize quando adequado; fixe semente; teste perplexidade e outros parâmetros disponíveis.", "tip": "Distâncias globais e separação visual não comprovam classes reais.", "tags": "visualização"}, {"id": 71, "cat": "PCA e clustering", "name": "Silhouette e avaliação dos clusters", "desc": "Compara coesão interna e separação entre grupos.", "steps": "Use uma implementação compatível; complemente a métrica com análise de domínio.", "tip": "Clusters precisam ser úteis e interpretáveis para o problema.", "tags": "silhueta"}, {"id": 72, "cat": "Automação", "name": "Table Row to Variable Loop Start", "desc": "Processa parâmetros de uma tabela linha a linha.", "steps": "Converta cada linha em variáveis; controle nós internos; use um Loop End compatível.", "tip": "Tipos das variáveis e configurações dos nós precisam coincidir.", "tags": "loop"}, {"id": 73, "cat": "Automação", "name": "Chunk Loop Start", "desc": "Processa uma tabela em blocos.", "steps": "Defina tamanho do bloco; execute transformação; reúna resultados no fim do loop.", "tip": "Agregações globais podem exigir uma etapa posterior à reunião dos blocos.", "tags": "lotes"}, {"id": 74, "cat": "Automação", "name": "Group Loop Start", "desc": "Executa etapas para cada grupo.", "steps": "Selecione chaves de agrupamento; processe cada grupo; consolide saídas.", "tip": "Grupos com poucas observações podem inviabilizar certos modelos.", "tags": "grupo"}, {"id": 75, "cat": "Automação", "name": "IF Switch / CASE Switch", "desc": "Escolhe caminhos condicionais no workflow.", "steps": "Crie uma condição ou variável; selecione o ramo ativo; una saídas com nós compatíveis.", "tip": "Confira o comportamento de ramos inativos e tipos das portas.", "tags": "condicional"}, {"id": 76, "cat": "Automação", "name": "Try / Catch", "desc": "Permite tratar falhas previstas dentro do fluxo.", "steps": "Delimite uma etapa sujeita a erro; defina alternativa; registre o motivo da falha.", "tip": "Não silencie erros sem guardar diagnóstico.", "tags": "erros"}, {"id": 77, "cat": "Automação", "name": "Caminhos portáveis", "desc": "Facilita mover workflows entre computadores.", "steps": "Use referências relativas ao workflow e recursos compartilhados quando suportado.", "tip": "Evite caminhos absolutos pessoais em um fluxo que será distribuído.", "tags": "path"}, {"id": 78, "cat": "Automação", "name": "Reprodutibilidade", "desc": "Permite repetir o experimento com condições conhecidas.", "steps": "Registre versão, extensões, origem dos dados, sementes e parâmetros.", "tip": "Uma semente fixa não garante igualdade entre versões ou bibliotecas diferentes.", "tags": "semente"}, {"id": 79, "cat": "Python e SQL", "name": "Python Script", "desc": "Integra bibliotecas Python ao workflow.", "steps": "Instale KNIME Python Integration; selecione ambiente com as bibliotecas; leia entrada e escreva saída pela API knime.scripting.io.", "tip": "Os exemplos aqui usam a integração atual, não a antiga API de Python.", "tags": "pandas script"}, {"id": 80, "cat": "Python e SQL", "name": "Python View", "desc": "Produz uma visualização Python no KNIME.", "steps": "Prepare dados; crie uma figura ou saída suportada; associe à saída de view da API.", "tip": "Confira bibliotecas e formatos aceitos pela versão instalada.", "tags": "matplotlib"}, {"id": 81, "cat": "Python e SQL", "name": "Ambiente Python", "desc": "Define intérprete e dependências usadas pelo nó.", "steps": "Use o ambiente fornecido quando suficiente ou configure um ambiente personalizado na integração.", "tip": "Biblioteca instalada em outro Python não fica automaticamente disponível no KNIME.", "tags": "conda"}, {"id": 82, "cat": "Python e SQL", "name": "DB Connector", "desc": "Abre conexão com um banco de dados.", "steps": "Escolha o connector apropriado; configure host, driver, banco e credenciais.", "tip": "Use contas com permissões adequadas e não exponha senhas em anotações.", "tags": "banco SQL"}, {"id": 83, "cat": "Python e SQL", "name": "DB Table Selector / DB Query Reader", "desc": "Seleciona ou consulta dados de um banco.", "steps": "Selecione tabela ou escreva SELECT; filtre na origem; leia apenas as colunas necessárias.", "tip": "Use mecanismos seguros de parametrização ao incorporar entradas externas.", "tags": "consulta"}, {"id": 84, "cat": "Python e SQL", "name": "DB nodes vs. table nodes", "desc": "Nós DB permitem compor operações executadas no banco antes de trazer dados.", "steps": "Filtre, agregue e una no banco quando apropriado; materialize resultados somente quando necessário.", "tip": "Inspecione a consulta gerada e os custos no banco.", "tags": "pushdown"}, {"id": 85, "cat": "IA generativa", "name": "KNIME AI Extension", "desc": "Adiciona nós para LLMs, embeddings, RAG e agentes.", "steps": "Instale a extensão; escolha provedor e modelos disponíveis; configure autenticação; teste com poucas linhas.", "tip": "Nós e disponibilidade de provedores variam por versão; consulte o guia oficial.", "tags": "LLM instalação"}, {"id": 86, "cat": "IA generativa", "name": "Prompt e saída estruturada", "desc": "Um prompt define tarefa, contexto, restrições e formato de resposta.", "steps": "Declare objetivo; delimite dados; forneça exemplo; solicite estrutura; valide a saída antes de usá-la.", "tip": "Saída de LLM pode conter erros mesmo quando parece bem formatada.", "tags": "prompt JSON"}, {"id": 87, "cat": "IA generativa", "name": "Embeddings", "desc": "Representam textos como vetores para busca por similaridade.", "steps": "Selecione modelo; gere embeddings de documentos; use o mesmo modelo para consultas.", "tip": "Vetores de modelos diferentes não devem ser misturados na mesma comparação.", "tags": "vetores"}, {"id": 88, "cat": "IA generativa", "name": "RAG", "desc": "Combina recuperação de documentos com geração de resposta.", "steps": "Divida documentos; gere embeddings; indexe; recupere trechos; envie contexto e pergunta ao LLM.", "tip": "Peça referências e verifique se elas realmente sustentam a resposta.", "tags": "retrieval"}, {"id": 89, "cat": "IA generativa", "name": "Agentes de IA", "desc": "Permitem que um modelo escolha ferramentas para cumprir uma tarefa.", "steps": "Defina ferramentas e permissões; limite iterações; registre ações; teste falhas e entradas adversas.", "tip": "Ações com efeito externo precisam de controles proporcionais ao impacto.", "tags": "agent"}, {"id": 90, "cat": "IA generativa", "name": "Avaliação de LLMs", "desc": "Mede qualidade, aderência e comportamento em um conjunto de casos.", "steps": "Prepare perguntas e respostas esperadas; avalie fundamentação, formato, custo e latência.", "tip": "Reavalie ao mudar modelo, prompt ou documentos.", "tags": "avaliação"}, {"id": 91, "cat": "IA generativa", "name": "Credenciais e custos", "desc": "Integrações podem enviar dados a serviços e consumir APIs cobradas.", "steps": "Configure credenciais com mecanismos próprios; estime volume, tokens e tentativas; monitore erros.", "tip": "Confira as políticas do provedor antes de enviar dados sensíveis.", "tags": "tokens privacidade"}, {"id": 92, "cat": "Receitas", "name": "Classificação · Iris", "desc": "Um fluxo inicial para prever espécie a partir de medidas.", "steps": "CSV Reader → Column Filter → Partitioning estratificado → Decision Tree Learner → Decision Tree Predictor → Scorer.", "tip": "Conecte ao Predictor tanto o modelo do Learner quanto a tabela de teste.", "tags": "iris classificação"}, {"id": 93, "cat": "Receitas", "name": "Comparar modelos · Heart", "desc": "Compara árvore, Random Forest e Naive Bayes de forma consistente.", "steps": "Leitura → divisão estratificada → pré-processamento ajustado no treino → três Learners → Predictors no mesmo teste → Scorer por modelo.", "tip": "Compare F1 e recall da classe de interesse; use validação para seleção.", "tags": "heart breast cancer"}, {"id": 94, "cat": "Receitas", "name": "Com PCA vs. sem PCA", "desc": "Avalia se a redução dimensional ajuda o classificador.", "steps": "Use a mesma divisão; ramo A: preparação → modelo; ramo B: preparação → PCA Compute/Apply → modelo; compare métricas.", "tip": "PCA deve ser aprendido só no treino e aplicado com o mesmo modelo ao teste.", "tags": "PCA random forest comparação"}, {"id": 95, "cat": "Receitas", "name": "Regressão · preços", "desc": "Prevê um valor contínuo e examina o erro.", "steps": "Reader → Partitioning → preparação → Linear Regression Learner → Regression Predictor → Numeric Scorer.", "tip": "Compare com baseline e observe erros em diferentes faixas do preço.", "tags": "carros vendas"}, {"id": 96, "cat": "Receitas", "name": "Segmentação de clientes", "desc": "Cria grupos com perfis de comportamento.", "steps": "Reader → GroupBy por cliente → seleção de atributos → Missing Value → Normalizer → K-Means → gráficos por cluster.", "tip": "Remova identificadores dos atributos de distância e descreva cada grupo.", "tags": "clientes"}, {"id": 97, "cat": "Receitas", "name": "Vendas por mês", "desc": "Resume faturamento e evolução temporal.", "steps": "Reader → String to Date&Time → extração de mês/ano → GroupBy → Sorter → Line Plot → Excel Writer.", "tip": "Use ano e mês juntos para não misturar meses de anos diferentes.", "tags": "vendas financeiro"}, {"id": 98, "cat": "Receitas", "name": "Validação cruzada", "desc": "Estima desempenho em múltiplas divisões da base de treino.", "steps": "X-Partitioner → ajuste de preparação no fold de treino → Learner → aplicação ao fold de validação → Predictor → X-Aggregator → avaliação.", "tip": "Guarde um teste final intocado; adapte portas e agregação à família de nós usada.", "tags": "k folds"}, {"id": 99, "cat": "Receitas", "name": "RAG · documentos", "desc": "Consulta uma coleção de textos com apoio de LLM.", "steps": "Leitura dos documentos → divisão em trechos → embeddings → armazenamento vetorial → recuperação → prompt com contexto → LLM → validação.", "tip": "É um roteiro conceitual; conectores e nomes dependem da extensão e do provedor.", "tags": "rag FAQ"}, {"id": 100, "cat": "Solução de problemas", "name": "Coluna não aparece", "desc": "O nó pode exigir um tipo específico ou receber um esquema desatualizado.", "steps": "Confira a tabela de entrada; execute nós anteriores; verifique tipos; reabra a configuração.", "tip": "Converter tipos incorretamente pode introduzir valores ausentes.", "tags": "erro schema"}, {"id": 101, "cat": "Solução de problemas", "name": "Predictor falha", "desc": "Modelo e tabela podem ter atributos incompatíveis.", "steps": "Compare nomes, tipos e codificação; aplique as transformações do treino ao teste.", "tip": "Salve o pipeline de preparação junto com o modelo.", "tags": "modelo erro"}, {"id": 102, "cat": "Solução de problemas", "name": "Workflow lento ou sem memória", "desc": "Dados, junções ou loops podem aumentar o volume processado.", "steps": "Filtre cedo; remova colunas desnecessárias; confira cardinalidade de joins; use DB nodes e blocos quando adequado.", "tip": "Aumentar memória não corrige uma junção que multiplicou linhas indevidamente.", "tags": "performance"}, {"id": 103, "cat": "Solução de problemas", "name": "Métrica boa demais", "desc": "Pode haver vazamento, duplicatas ou avaliação no treino.", "steps": "Confira origem do alvo; proxies; sobreposição de grupos; transformação antes do split; tabela recebida pelo Scorer.", "tip": "Valide também com uma divisão coerente com o uso real.", "tags": "leakage"}, {"id": 104, "cat": "Solução de problemas", "name": "Nó não encontrado", "desc": "O nome, extensão ou disponibilidade pode ter mudado.", "steps": "Busque o nome em inglês no Hub; verifique instalação e compatibilidade; consulte a descrição atual.", "tip": "Este guia é amplo, mas não substitui o catálogo completo de extensões.", "tags": "extensões"}, {"id": 105, "cat": "Solução de problemas", "name": "API ou Python falha", "desc": "Pode faltar dependência, credencial ou compatibilidade de ambiente.", "steps": "Leia a mensagem completa; valide ambiente; teste entrada pequena; confira autenticação e status da API.", "tip": "Registre diagnóstico sem expor tokens ou senhas.", "tags": "debug"}];
const CATEGORIES = ["Fundamentos", "Entrada e saída", "Limpeza e transformação", "Exploração e gráficos", "Machine learning", "Validação e métricas", "PCA e clustering", "Automação", "Python e SQL", "IA generativa", "Receitas", "Solução de problemas"];